static id<MTLDevice> gpu;static id<MTLCommandQueue> queue;static id<MTLRenderPipelineState> pipeline;
static double start;static CAMetalLayer *layer;
static void render(id<MTLTexture> texture,float t,id<CAMetalDrawable> drawable){MTLRenderPassDescriptor *pass=[MTLRenderPassDescriptor renderPassDescriptor];pass.colorAttachments[0].texture=texture;pass.colorAttachments[0].loadAction=MTLLoadActionDontCare;pass.colorAttachments[0].storeAction=MTLStoreActionStore;id<MTLCommandBuffer> cb=[queue commandBuffer];id<MTLRenderCommandEncoder> enc=[cb renderCommandEncoderWithDescriptor:pass];float u[4]={texture.width,texture.height,t,0};[enc setRenderPipelineState:pipeline];[enc setFragmentBytes:u length:sizeof(u) atIndex:0];[enc drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:3];[enc endEncoding];if(drawable)[cb presentDrawable:drawable];[cb commit];[cb waitUntilCompleted];}
@interface Demo:NSObject<NSApplicationDelegate>
@property(strong) NSWindow *window;
@end
@implementation Demo
-(BOOL)applicationShouldTerminateAfterLastWindowClosed:(NSApplication*)app{return YES;}
-(void)tick:(NSTimer*)timer{float t=NSProcessInfo.processInfo.systemUptime-start;if(t>=96){[NSApp terminate:nil];return;}@autoreleasepool{NSSize s=self.window.contentView.bounds.size;CGFloat scale=self.window.backingScaleFactor;layer.frame=self.window.contentView.bounds;float factor=fmin(1.,1280./(s.width*scale));layer.drawableSize=CGSizeMake(s.width*scale*factor,s.height*scale*factor);id<CAMetalDrawable> d=[layer nextDrawable];if(d)render(d.texture,t,d);}}
-(void)applicationDidFinishLaunching:(NSNotification*)n{self.window=[[NSWindow alloc]initWithContentRect:NSMakeRect(0,0,1152,648) styleMask:NSWindowStyleMaskTitled|NSWindowStyleMaskClosable|NSWindowStyleMaskResizable backing:NSBackingStoreBuffered defer:NO];self.window.title=@"Dem6 / 64K — ←/↑ previous · →/↓ next · Esc: quit · F: fullscreen";layer=[CAMetalLayer layer];layer.device=gpu;layer.pixelFormat=MTLPixelFormatBGRA8Unorm;self.window.contentView.wantsLayer=YES;self.window.contentView.layer=layer;[self.window center];[self.window makeKeyAndOrderFront:nil];[NSApp activateIgnoringOtherApps:YES];[NSEvent addLocalMonitorForEventsMatchingMask:NSEventMaskKeyDown handler:^NSEvent*(NSEvent *e){if(e.keyCode==53||([e.charactersIgnoringModifiers isEqualToString:@"q"]&&(e.modifierFlags&NSEventModifierFlagCommand))){[NSApp terminate:nil];return nil;}if(e.keyCode==3||[e.charactersIgnoringModifiers.lowercaseString isEqualToString:@"f"]||[e.charactersIgnoringModifiers.lowercaseString isEqualToString:@"а"]){[self.window toggleFullScreen:nil];return nil;}if(e.keyCode==124||e.keyCode==125||e.keyCode==123||e.keyCode==126){double now=NSProcessInfo.processInfo.systemUptime,elapsed=now-start;int current=(int)(elapsed/32.);int target=e.keyCode==124||e.keyCode==125?MIN(2,current+1):MAX(0,current-1);start=now-target*32.;return nil;}return e;}];start=NSProcessInfo.processInfo.systemUptime;[NSTimer scheduledTimerWithTimeInterval:1./60 target:self selector:@selector(tick:) userInfo:nil repeats:YES];}
@end
int main(int argc,char **argv){@autoreleasepool{gpu=MTLCreateSystemDefaultDevice();if(!gpu){fprintf(stderr,"Metal device unavailable\n");return 1;}NSError *err=nil;id<MTLLibrary> lib=[gpu newLibraryWithSource:@SHADER options:nil error:&err];MTLRenderPipelineDescriptor *desc=[MTLRenderPipelineDescriptor new];desc.vertexFunction=[lib newFunctionWithName:@"vert"];desc.fragmentFunction=[lib newFunctionWithName:@"frag"];desc.colorAttachments[0].pixelFormat=MTLPixelFormatBGRA8Unorm;pipeline=[gpu newRenderPipelineStateWithDescriptor:desc error:&err];if(!pipeline){fprintf(stderr,"%s\n",err.description.UTF8String);return 2;}queue=[gpu newCommandQueue];if(argc==4&&!strcmp(argv[1],"--capture")){MTLTextureDescriptor *td=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatBGRA8Unorm width:1280 height:720 mipmapped:NO];td.usage=MTLTextureUsageRenderTarget;td.storageMode=MTLStorageModeShared;id<MTLTexture> tex=[gpu newTextureWithDescriptor:td];render(tex,atof(argv[2]),nil);unsigned char *pixels=malloc(1280*720*4);[tex getBytes:pixels bytesPerRow:1280*4 fromRegion:MTLRegionMake2D(0,0,1280,720) mipmapLevel:0];NSBitmapImageRep *rep=[[NSBitmapImageRep alloc]initWithBitmapDataPlanes:NULL pixelsWide:1280 pixelsHigh:720 bitsPerSample:8 samplesPerPixel:4 hasAlpha:YES isPlanar:NO colorSpaceName:NSDeviceRGBColorSpace bytesPerRow:5120 bitsPerPixel:32];unsigned char *dst=rep.bitmapData;for(int i=0;i<1280*720;i++){dst[i*4]=pixels[i*4+2];dst[i*4+1]=pixels[i*4+1];dst[i*4+2]=pixels[i*4];dst[i*4+3]=255;}[[rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}]writeToFile:@(argv[3]) atomically:YES];free(pixels);return 0;}[NSApplication sharedApplication];[NSApp setActivationPolicy:NSApplicationActivationPolicyRegular];Demo *demo=[Demo new];NSApp.delegate=demo;[NSApp run];}return 0;}
